async (page) => {
  const fs = require('fs');
  const path = require('path');

  const root = '/tmp/mcp-workspace';
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
  const emails = new Set();

  function walk(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) {
        walk(full);
      } else if (e.isFile()) {
        try {
          const buf = fs.readFileSync(full);
          // Heuristic: skip binary files (very simple check)
          const sample = buf.slice(0, 8000).toString('utf8');
          if (sample.includes('\u0000')) continue;
          const text = buf.toString('utf8');
          const matches = text.match(emailRegex);
          if (matches) {
            for (const m of matches) emails.add(m);
          }
        } catch (err) {
          // skip unreadable
        }
      }
    }
  }

  walk(root);
  const sorted = [...emails].sort((a, b) => a.localeCompare(b));
  const output = sorted.join('\n') + (sorted.length ? '\n' : '');
  fs.writeFileSync(path.join(root, 'unique_emails.txt'), output);
  return { count: sorted.length, emails: sorted };
};

